export const skeletalTrackKeyContract={commands:['skeletal.track.create','skeletal.track.keys','skeletal.track.read'],asset:'Existing v1 .hbskeletalclip.json; stable named TRS/indexed channels and morph arrays.',edits:'edits[{index,time?,values?}], remove[index], insert[{time,values?}], interpolation? step/linear/smooth. Indices refer to the original track; duplicate/removed edits reject. Missing inserted values sample the post-edit track using the actual Float32 interpolant.',precision:'Authored doubles retained; final times must stay distinct in Float32 runtime precision. Full quaternions normalize and reject near-zero; quaternion Smooth rejected explicitly. Euler rotation values use radians.',publication:'One document Undo/CAS after complete validation. Generator yields every4096 output keys; cancellation publishes nothing. Unchanged tracks/metadata remain structurally shared; no object per original key.',read:'Paged keys and channels only; no whole values-array clone/materialization. Last-key deletion removes that track; duration/notify/metadata curves remain unchanged.',cost:'Existing full clip validation/Undo snapshot and authored flat selected-track arrays still scale with data. Not constant-time editing or an FPS claim.'};
